mapper.select:
SELECT s_start.id AS departureStationId, -- 出发站ID s_end.id AS arrivalStationId, -- 到达站ID tss_a.train_id AS trainId, -- 列车ID tss_a.departure_time AS departureTime, -- 出发时间 tss_b.arrival_time AS arrivalTime, -- 到达时间 tss_a.sequence AS startSequence, -- 出发站站序 tss_b.sequence AS endSequence -- 到达站站序 FROM train_stop_station tss_a -- 先取出发站经停记录 INNER JOIN train_stop_station tss_b ON tss_a.train_id = tss_b.train_id AND tss_a.sequence < tss_b.sequence -- 先关联同一列车的到达站经停记录 INNER JOIN station s_start ON tss_a.station_id = s_start.id -- 再关联出发站信息 INNER JOIN station s_end ON tss_b.station_id = s_end.id -- 最后关联到达站信息
AND s_start.`name` LIKE CONCAT('%', #{fromStation}, '%')
AND s_start.`name` = #{departure}
-- 提取 departure_time 的日期部分（如 2025-11-11），与 LocalDate 参数比较 AND DATE(tss_a.departure_time) = #{departureDate}
AND s_end.`name` LIKE CONCAT('%', #{toStation}, '%')
AND s_end.`name` = #{arrival}
